    "schemas": {
      "UserSummary": {
        "type": "object",
        "required": [
          "total",
          "active"
        ],
        "properties": {
          "total": {
            "type": "integer"
          },
          "active": {
            "type": "integer"
          },
          "ratio": {
            "type": "number"
          },
