              "$ref": "#/components/schemas/Role"
            }
          }
        }
      },
      "Role": {
        "type": "string",
        "enum": [
          "admin",
          "member",
          "guest"
        ]
      },
      "ImportResult": {
        "type": "object",
        "required": [
          "imported"
        ],
        "properties": {
          "imported": {
            "type": "integer"
          },
          "skipped": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "row"
              ],
              "properties": {
                "row": {
                  "type": "integer"
                },
                "reason": {
                  "type": "string"
                }
              }
            }
          },
          "dry-run": {
            "type": "boolean"
          },
          "meta": {
            "type": "object",
            "additionalProperties": true
          }
        }
      },
      "Error": {
        "type": "object",
        "required": [
          "code",
          "message"
        ],
        "properties": {
          "code": {
            "type": "string"
          },
          "message": {
