          "schema": {
            "type": "string"
          },
          "file": {
            "mode": "append"
          }
        }
      ],
      "commands": {
        "users": {
          "summary": "Show a summary of all users.",
          "options": [
            {
              "name": "all",
              "aliases": [
                "a"
              ],
              "description": "Include deactivated users.",
              "schema": {
                "type": "boolean"
              }
            }
          ],
          "exits": {
            "0": {
              "description": "Summary written.",
              "stdout": {
                "format": "json",
                "schema": {
                  "$ref": "#/components/schemas/UserSummary"
                }
              }
            }
          }
        },
        "users.import": {
          "summary": "Import users from a file. The file is read once and every row is validated before any user is written, so a failed import leaves the directory unchanged.",
          "arguments": [
            {
              "name": "file",
              "description": "CSV file to import.",
              "required": true,
              "schema": {
                "type": "string"
              },
              "file": {
                "mode": "read"
              }
            }
          ],
          "options": [
            {
              "name": "dry-run",
              "aliases": [
                "n"
              ],
              "description": "Validate without writing.",
              "schema": {
                "type": "boolean"
              }
            },
            {
              "name": "format",
              "aliases": [
                "f"
              ],
              "value_name": "fmt",
              "description": "Input format.",
              "schema": {
                "type": "string",
                "enum": [
                  "csv",
                  "tsv"
                ],
                "default": "csv"
              }
            },
            {
              "name": "tag",
              "aliases": [
                "t"
              ],
              "value_name": "tag",
              "description": "Tag to attach to every imported user.",
              "repeatable": true,
              "schema": {
                "type": "string"
              }
            },
            {
              "name": "color",
              "description": "Colorize the report.",
              "schema": {
                "type": "boolean",
                "default": true
              }
            },
            {
              "name": "no-cache",
              "description": "Bypass the import cache.",
              "schema": {
                "type": "boolean"
              }
            },
            {
              "name": "limit",
              "value_name": "n",
              "description": "Stop after this many rows.",
              "schema": {
                "type": "integer"
              }
            },
            {
              "name": "report",
              "value_name": "path",
              "description": "Write a report to this file.",
              "schema": {
                "type": "string"
              },
              "file": {
                "mode": "write"
              }
            },
            {
              "name": "all",
              "description": "Import deactivated users too.",
              "schema": {
                "type": "boolean"
              }
            }
          ],
          "effects": {
            "risk_level": "medium",
            "writes": [
              {
                "target": "user directory",
                "description": "imported users",
                "idempotent": true,
                "idempotency_key": "email"
              }
            ]
          },
          "exits": {
            "0": {
              "description": "Import succeeded.",
              "stdout": {
                "format": "json",
                "schema": {
                  "$ref": "#/components/schemas/ImportResult"
                }
              }
            },
            "2": {
              "description": "Invalid arguments.",
              "stderr": {
                "format": "json",
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            },
            "10": {
              "description": "Partial import.",
              "stdout": {
                "required": false,
                "format": "json",
                "schema": {
                  "$ref": "#/components/schemas/ImportResult"
                }
              },
              "stderr": {
                "format": "json",
                "schema": {
                  "$ref": "#/components/schemas/Error"
                }
              }
            }
          }
        },
        "users.remove": {
          "summary": "Remove users.",
          "arguments": [
            {
              "name": "ids",
              "description": "User IDs.",
              "required": true,
              "variadic": true
            }
          ],
          "options": [
            {
              "name": "force",
              "description": "Remove without archiving.",
              "schema": {
                "type": "boolean"
              },
              "effects": {
                "risk_level": "high",
                "writes": [
                  {
                    "target": "archive",
                    "destructive": true
                  }
                ]
              }
            }
          ],
          "effects": {
            "risk_level": "medium",
            "requires_confirmation": false,
            "writes": [
              "users-db"
            ]
          },
          "exits": {
            "0": {
              "description": "Removed."
            },
            "3": {
              "description": "Some users were not found."
            }
          }
        }
      }
    }
  },
  "components": {
    "schemas": {
      "UserSummary": {
        "type": "object",
        "required": [
          "total",
          "active"
        ],
        "properties": {
          "total": {
            "type": "integer"
          },
          "active": {
            "type": "integer"
          },
          "ratio": {
            "type": "number"
          },
          "roles": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/Role"
            }
          }
        }
      },
      "Role": {
        "type": "string",
        "enum": [
          "admin",
          "member",
          "guest"
        ]
      },
      "ImportResult": {
        "type": "object",
        "required": [
          "imported"
        ],
        "properties": {
          "imported": {
            "type": "integer"
          },
          "skipped": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "row"
              ],
              "properties": {
                "row": {
                  "type": "integer"
                },
                "reason": {
                  "type": "string"
                }
              }
            }
          },
          "dry-run": {
            "type": "boolean"
          },
          "meta": {
            "type": "object",
            "additionalProperties": true
          }
        }
      },
      "Error": {
        "type": "object",
        "required": [
          "code",
          "message"
        ],
        "properties": {
          "code": {
            "type": "string"
          },
          "message": {
            "type": "string"
          },
          "details": {
            "oneOf": [
              {
                "type": "string"
              },
              {
                "type": "object",
                "additionalProperties": true
              }
            ]
          }
        }
      },
      "AuditedImport": {
        "allOf": [
          {
            "$ref": "#/components/schemas/ImportResult"
          },
          {
            "type": "object",
            "required": [
              "auditor"
            ],
            "properties": {
              "auditor": {
                "type": "string"
              }
            }
          }
        ]
      }
    }
  }
